COINS = {5, 10, 25, 100}


class VendingMachine:
    def __init__(self, items: list[list]):
        self.stock = {name: qty for name, _, qty in items}
        self.price = {name: price for name, price, _ in items}
        self.credit = 0
        self.pending = None
        self.state = "IDLE"

    def insertCoin(self, coin: int) -> str:
        if self.state == "DISPENSING":
            return "REJECTED"
        if coin not in COINS:
            return "REJECTED"
        self.credit += coin
        self.state = "HAS_CREDIT"
        return "OK"

    def select(self, name: str) -> str:
        if self.state == "DISPENSING":
            return "BUSY"
        if name not in self.price:
            return "UNKNOWN_ITEM"
        if self.stock[name] == 0:
            return "SOLD_OUT"
        if self.state == "IDLE":
            return "NO_CREDIT"
        if self.credit < self.price[name]:
            return "INSUFFICIENT_CREDIT"
        self.credit -= self.price[name]
        self.stock[name] -= 1
        self.pending = name
        self.state = "DISPENSING"
        return "OK"

    def dispense(self) -> str:
        if self.state != "DISPENSING":
            return "NOTHING_SELECTED"
        item = self.pending
        self.pending = None
        self.state = "HAS_CREDIT" if self.credit > 0 else "IDLE"
        return item

    def refund(self) -> int:
        if self.state == "DISPENSING":
            return -1
        amount = self.credit
        self.credit = 0
        self.state = "IDLE"
        return amount

    def getState(self) -> str:
        return self.state

COINS = {5, 10, 25, 100}


class State:
    """Default behaviour: every action is illegal unless a subclass allows it."""

    name = ""

    def insertCoin(self, m, coin: int) -> str:
        return "REJECTED"

    def select(self, m, name: str) -> str:
        return "BUSY"

    def dispense(self, m) -> str:
        return "NOTHING_SELECTED"

    def refund(self, m) -> int:
        amount = m.credit
        m.credit = 0
        m.state = IDLE
        return amount


class Idle(State):
    name = "IDLE"

    def insertCoin(self, m, coin: int) -> str:
        if coin not in COINS:
            return "REJECTED"
        m.credit += coin
        m.state = HAS_CREDIT
        return "OK"

    def select(self, m, name: str) -> str:
        if name not in m.price:
            return "UNKNOWN_ITEM"
        if m.stock[name] == 0:
            return "SOLD_OUT"
        return "NO_CREDIT"


class HasCredit(State):
    name = "HAS_CREDIT"

    def insertCoin(self, m, coin: int) -> str:
        if coin not in COINS:
            return "REJECTED"
        m.credit += coin
        return "OK"

    def select(self, m, name: str) -> str:
        if name not in m.price:
            return "UNKNOWN_ITEM"
        if m.stock[name] == 0:
            return "SOLD_OUT"
        if m.credit < m.price[name]:
            return "INSUFFICIENT_CREDIT"
        m.credit -= m.price[name]
        m.stock[name] -= 1
        m.pending = name
        m.state = DISPENSING
        return "OK"


class Dispensing(State):
    name = "DISPENSING"

    def dispense(self, m) -> str:
        item = m.pending
        m.pending = None
        m.state = HAS_CREDIT if m.credit > 0 else IDLE
